From d7f6ecbeeba32e4ee3c676e082a350fb3e78076d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:12:13 +0100
Subject: [PATCH] openconnect: report a cancelled web login as cancelled

The web login callback always reported success, even when the dialog
was cancelled, so libopenconnect went on with an empty form and kded
crashed; it now returns a cancelled result, and the flag is set first.

BUG: 486076
---
 vpn/openconnect/openconnectauth.cpp             | 2 +-
 vpn/openconnect/openconnectauthworkerthread.cpp | 3 +++
 2 files changed, 4 insertions(+), 1 deletion(-)

diff --git a/vpn/openconnect/openconnectauth.cpp b/vpn/openconnect/openconnectauth.cpp
index a02b55b67..381dcd7af 100644
--- a/vpn/openconnect/openconnectauth.cpp
+++ b/vpn/openconnect/openconnectauth.cpp
@@ -161,11 +161,11 @@ OpenconnectAuthWidget::OpenconnectAuthWidget(const NetworkManager::VpnSetting::P
 OpenconnectAuthWidget::~OpenconnectAuthWidget()
 {
     Q_D(OpenconnectAuthWidget);
+    d->userQuit = true;
     QSemaphore *webEngineCancel = d->waitForWebEngineFinish.fetchAndStoreRelaxed(nullptr);
     if (webEngineCancel) {
         webEngineCancel->release();
     }
-    d->userQuit = true;
     if (write(d->cancelPipes[1], "x", 1)) {
         // not a lot we can do
     }
diff --git a/vpn/openconnect/openconnectauthworkerthread.cpp b/vpn/openconnect/openconnectauthworkerthread.cpp
index 7728f084a..fb6ca7cdb 100644
--- a/vpn/openconnect/openconnectauthworkerthread.cpp
+++ b/vpn/openconnect/openconnectauthworkerthread.cpp
@@ -220,6 +220,9 @@ int OpenconnectAuthWorkerThread::openWebEngineP(__attribute__((unused)) struct o

     Q_EMIT openWebEngine(loginUri, &waitForWebEngineFinish);
     waitForWebEngineFinish.acquire();
+    if (*m_userDecidedToQuit) {
+        return OC_FORM_RESULT_CANCELLED;
+    }

     return 0;
 }
